import express from "express";
import { ingestUpload } from "./uploads/ingest-upload.js";
const app = express();
app.post("/admin/upload", (_req, res) => res.json(ingestUpload("report.csv")));

export function ingestUpload(fileName: string) {
  if (!fileName.endsWith(".csv")) throw new Error("invalid upload");
  return { status: "accepted", fileName };
}

import { expect, it } from "vitest";
import { ingestUpload } from "./ingest-upload.js";
it("covers csv upload ingestion", () => expect(ingestUpload("a.csv").status).toBe("accepted"));

export function ingestUpload(fileName: string) {
  if (!fileName.endsWith(".csv") && !fileName.endsWith(".tsv")) throw new Error("invalid upload");
  return { status: "accepted", fileName };
}
